"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8963],{18963:e=>{e.exports=JSON.parse('{"slug":"bessent-khe-lifen-peregovory-tramp-si","locale":"zh","title":"贝森特与何立峰在纽约会谈，距离特朗普与习近平会面还有4天","description":"美国财长斯科特\xb7贝森特周日在纽约会见中国副总理何立峰，为周四特朗普与习近平会面做准备。核心是两大经济体能否延长贸易休战；对俄罗斯，则关系到石油需求。","blocks":[{"id":"b001","kind":"paragraph","text":"贝森特在X发文称，在特朗普与习近平华盛顿“历史性会面”前，他与何立峰“继续讨论美中经贸关系”，并附上国旗前的礼宾照片，未提供其他细节。随后他称会谈成功，重点是贸易与人工智能。新华社确认会谈。两国元首将在周四九月24日会面。"},{"id":"b002","kind":"paragraph","text":"预告中的议题包括关税、人工智能竞争、半导体出口管制、中国电动车在美生产的可能性，背景还有台湾与伊朗。五月领导人会面后关系转差，美国官员公开指责中国未履行一年期贸易休战条款。中国对关键矿物与稀土的出口限制也笼罩会谈，已使美国及其他制造商供应中断。"},{"id":"b003","kind":"paragraph","text":"“贸易休战”本身很简单：双方一年前约定不再相互加税，不新增限制。这是有截止日的争端暂停，相当于先不吵，再决定是否续期。期限临近正是周四的悬念。重点未必是签署重大协议，而是可能什么都不签；休战到期后，双方又可自由采取关税行动。"},{"id":"b004","kind":"paragraph","text":"稀土在谈判中构成杠杆。电子产品、电池和武器需要它们，而中国出口受限。类似汽车厂只有一个零件供应商，对方决定价格与交期，汽车厂缺件就无法装车。因此断供比关税更敏感：关税只是零件变贵，断供则根本没有零件。"},{"id":"b005","kind":"paragraph","text":"市场暂时观望而非下注。周一美股指数期货小幅上涨，美元维持窄幅波动，没人愿猜结果。周四结局未知，两位领导人都善于在最后一刻同时展示达成协议与拂袖离去的可能。"},{"id":"b006","kind":"paragraph","text":"对俄罗斯没有直接渠道：议程并不涉及俄罗斯进口或卢布。传导链较长。美中若再加关税，全球贸易减速，石油需求随之下降；石油又是预算收入和汇率支撑。若达成协议，来自这一路径的油价压力消失。目前没有幅度估计。"},{"id":"b007","kind":"paragraph","text":"普通人应关注，而不宜仅凭这条新闻行动。“峰会前以防万一”买外汇，是为尚未发生的事件向银行支付买卖价差。但说大国贸易战与俄罗斯无关也不成立：它通过油价影响预算与汇率，只是往往延后数月。"}],"sources":[{"label":"https://www.interfax.ru/world/1117310","url":"https://www.interfax.ru/world/1117310"},{"label":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html","url":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html"},{"label":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video","url":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video"},{"label":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20","url":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20"},{"label":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap","url":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap"}],"sourceBodySha256":"c1bc79749a4e70a8e26a07aaaf0de06d665d61f9e8ea4735408da5f270991985"}')}}]);